#!/usr/bin/env python3
"""Generate the first 10 FOP lab programs as C source files."""
from pathlib import Path

PROGRAMS = {
    '01_hello.c': '/* Program 1: Print HELLO */\n#include <stdio.h>\n\nint main(void) {\n    printf("HELLO\\n");\n    return 0;\n}\n',
    '02_add_two_numbers.c': '/* Program 2: Add two numbers */\n#include <stdio.h>\n\nint main(void) {\n    double a, b;\n    printf("Enter two numbers: ");\n    if (scanf("%lf %lf", &a, &b) != 2) {\n        printf("Invalid input.\\n");\n        return 1;\n    }\n\n    printf("Sum = %.2f\\n", a + b);\n    return 0;\n}\n',
    '03_simple_interest.c': '/* Program 3: Calculate simple interest */\n#include <stdio.h>\n\nint main(void) {\n    double principal, rate, time, interest;\n    printf("Enter principal, annual rate (%%), and time in years: ");\n    if (scanf("%lf %lf %lf", &principal, &rate, &time) != 3) {\n        printf("Invalid input.\\n");\n        return 1;\n    }\n\n    interest = principal * rate * time / 100.0;\n    printf("Simple interest = %.2f\\n", interest);\n    printf("Total amount = %.2f\\n", principal + interest);\n    return 0;\n}\n',
    '04_absolute_value.c': '/* Program 4: Find the absolute value of a number */\n#include <stdio.h>\n#include <math.h>\n\nint main(void) {\n    double number;\n    printf("Enter a number: ");\n    if (scanf("%lf", &number) != 1) {\n        printf("Invalid input.\\n");\n        return 1;\n    }\n\n    printf("Absolute value = %.2f\\n", fabs(number));\n    return 0;\n}\n',
    '05_swap_two_numbers.c': '/* Program 5: Swap the values of two numbers */\n#include <stdio.h>\n\nint main(void) {\n    double a, b, temp;\n    printf("Enter two numbers: ");\n    if (scanf("%lf %lf", &a, &b) != 2) {\n        printf("Invalid input.\\n");\n        return 1;\n    }\n\n    printf("Before swapping: a = %.2f, b = %.2f\\n", a, b);\n    temp = a;\n    a = b;\n    b = temp;\n    printf("After swapping:  a = %.2f, b = %.2f\\n", a, b);\n    return 0;\n}\n',
    '06_gross_salary.c': '/* Program 6: Calculate gross salary\n   Assumption: gross salary = basic salary + HRA + DA.\n   Follow your instructor\'s formula if it differs. */\n#include <stdio.h>\n\nint main(void) {\n    double basic, hra, da;\n    printf("Enter basic salary, HRA, and DA: ");\n    if (scanf("%lf %lf %lf", &basic, &hra, &da) != 3) {\n        printf("Invalid input.\\n");\n        return 1;\n    }\n\n    printf("Gross salary = %.2f\\n", basic + hra + da);\n    return 0;\n}\n',
    '07_even_or_odd.c': '/* Program 7: Check whether an integer is even or odd */\n#include <stdio.h>\n\nint main(void) {\n    long long number;\n    printf("Enter an integer: ");\n    if (scanf("%lld", &number) != 1) {\n        printf("Invalid input.\\n");\n        return 1;\n    }\n\n    if (number % 2 == 0)\n        printf("%lld is even.\\n", number);\n    else\n        printf("%lld is odd.\\n", number);\n\n    return 0;\n}\n',
    '08_greatest_of_three.c': '/* Program 8: Find the greatest of three numbers */\n#include <stdio.h>\n\nint main(void) {\n    double a, b, c, greatest;\n    printf("Enter three numbers: ");\n    if (scanf("%lf %lf %lf", &a, &b, &c) != 3) {\n        printf("Invalid input.\\n");\n        return 1;\n    }\n\n    greatest = a;\n    if (b > greatest)\n        greatest = b;\n    if (c > greatest)\n        greatest = c;\n\n    printf("Greatest number = %.2f\\n", greatest);\n    return 0;\n}\n',
    '09_student_grade.c': '/* Program 9: Find a student\'s grade from marks\n   Example scale only; replace with your college\'s official scale if supplied. */\n#include <stdio.h>\n\nint main(void) {\n    double marks;\n    printf("Enter marks out of 100: ");\n    if (scanf("%lf", &marks) != 1) {\n        printf("Invalid input.\\n");\n        return 1;\n    }\n\n    if (marks < 0 || marks > 100)\n        printf("Invalid marks. Enter a value from 0 to 100.\\n");\n    else if (marks >= 90)\n        printf("Grade: A\\n");\n    else if (marks >= 80)\n        printf("Grade: B\\n");\n    else if (marks >= 70)\n        printf("Grade: C\\n");\n    else if (marks >= 60)\n        printf("Grade: D\\n");\n    else if (marks >= 40)\n        printf("Grade: E\\n");\n    else\n        printf("Grade: F (Fail)\\n");\n\n    return 0;\n}\n',
    '10_factorial_or_divisors.c': '/* Program 10: Calculate factorial OR print positive divisors */\n#include <stdio.h>\n\nint main(void) {\n    int choice;\n    printf("Choose an option:\\n");\n    printf("1. Calculate factorial\\n");\n    printf("2. Print positive divisors\\n");\n    printf("Enter choice (1 or 2): ");\n\n    if (scanf("%d", &choice) != 1) {\n        printf("Invalid input.\\n");\n        return 1;\n    }\n\n    if (choice == 1) {\n        int n, i;\n        unsigned long long factorial = 1;\n\n        printf("Enter a non-negative integer (0 to 20): ");\n        if (scanf("%d", &n) != 1 || n < 0 || n > 20) {\n            printf("Please enter an integer from 0 to 20.\\n");\n            return 1;\n        }\n\n        for (i = 2; i <= n; i++)\n            factorial *= (unsigned long long)i;\n\n        printf("%d! = %llu\\n", n, factorial);\n    } else if (choice == 2) {\n        int n, i;\n        printf("Enter a positive integer: ");\n        if (scanf("%d", &n) != 1 || n <= 0) {\n            printf("Please enter a positive integer.\\n");\n            return 1;\n        }\n\n        printf("Positive divisors of %d: ", n);\n        for (i = 1; i <= n; i++) {\n            if (n % i == 0)\n                printf("%d ", i);\n        }\n        printf("\\n");\n    } else {\n        printf("Invalid choice.\\n");\n    }\n\n    return 0;\n}\n',
}

def main():
    folder = Path(__file__).resolve().parent / "FOP_First_10_C_Programs"
    folder.mkdir(exist_ok=True)
    for filename, source in PROGRAMS.items():
        (folder / filename).write_text(source, encoding="utf-8")
    print(f"Created {len(PROGRAMS)} C programs in: {folder}")

if __name__ == "__main__":
    main()
